1: // Package nmap provides idiomatic `nmap` bindings for go developers.
2: package nmap
3: 
4: import (
5: 	"context"
6: 	"errors"
7: 	"fmt"
8: 	"os"
9: 	"os/exec"
10: 	"syscall"
11: 
12: 	"github.com/mattn/go-isatty"
13: )
14: 
15: // ScanRunner represents something that can run a scan.
16: type ScanRunner interface {
17: 	Run(ctx context.Context) (*Run, error)
18: }
19: 
20: // AsyncScanRunner represents something that can run a scan asynchronously.
21: type AsyncScanRunner interface {
22: 	RunAsync(ctx context.Context) (<-chan []byte, <-chan []byte, <-chan RunResult, error)
23: }
24: 
25: // Scanner represents n Nmap scanner.
26: type Scanner struct {
27: 	modifySysProcAttr func(*syscall.SysProcAttr)
28: 
29: 	args       []string
30: 	binaryPath string
31: 
32: 	portFilter func(Port) bool
33: 	hostFilter func(Host) bool
34: 
35: 	progressHandler func(TaskProgress)
36: 
37: 	interactive bool
38: 	toFile      *string
39: }
40: 
41: // RunResult represents the result of an asynchronous run.
42: type RunResult struct {
43: 	Result *Run
44: 	Err    error
45: }
46: 
47: // Option is a function that is used for grouping of Scanner options.
48: // Option adds or removes nmap command line arguments.
49: type Option func(*Scanner) error
50: 
51: // NewScanner creates a new Scanner, and can take options to apply to the scanner.
