102		var warnings []string
103		warnings, errStdout := checkStdErr(stderr)
104		if errStdout != nil {
105			return result, errStdout
106		}
107	
108		contents := stdout.Bytes()
109	
110		// Parse nmap xml output. Usually nmap always returns valid XML, even if there is a scan error.
111		// Potentially available warnings are returned too, but probably not the reason for a broken XML.
112		var err error
113		if s.toFile != nil {
114			contents, err = os.ReadFile(*s.toFile)
115			if err != nil {
116				return result, fmt.Errorf("reading output file %s: %w", *s.toFile, err)
117			}
118	
119			chmodErr := os.Chmod(*s.toFile, 0o600)
120			if chmodErr != nil {
