186	// checkStdErr writes the output of stderr to the warnings array.
187	// It also processes nmap stderr output containing none-critical errors and warnings.
188	func checkStdErr(stderr *bytes.Buffer) (warnings []string, err error) {
189		if stderr.Len() <= 0 {
190			return nil, nil
191		}
192	
193		stderrSplit := strings.SplitSeq(strings.Trim(stderr.String(), "\n "), "\n")
194	
195		// Check for warnings that inevitably lead to parsing errors, hence, have priority.
196		for warning := range stderrSplit {
197			warnings = append(warnings, strings.Trim(warning, " "))
198			switch {
199			case strings.Contains(warning, "Malloc Failed!"):
200				return warnings, ErrMallocFailed
201			case strings.Contains(warning, "requires root privileges."):
202				return warnings, ErrRequiresRoot
203			default:
204			}
205		}
206		return warnings, nil
207	}
