11	func (s *Scanner) runAsync(ctx context.Context) (<-chan []byte, <-chan []byte, <-chan RunResult, error) {
12		cmd := s.newCmd(ctx)
13	
14		stdoutPipe, err := cmd.StdoutPipe()
15		if err != nil {
16			return nil, nil, nil, err
17		}
18	
19		stderrPipe, err := cmd.StderrPipe()
20		if err != nil {
21			return nil, nil, nil, err
22		}
23	
24		err = cmd.Start()
25		if err != nil {
26			return nil, nil, nil, err
27		}
28	
29		stdoutCh := make(chan []byte, 16)
30		stderrCh := make(chan []byte, 16)
31		resultCh := make(chan RunResult, 1)
32	
33		var stdout, stderr bytes.Buffer
34		stdoutWriter := io.MultiWriter(&stdout, channelWriter{ch: stdoutCh})
35		stderrWriter := io.MultiWriter(&stderr, channelWriter{ch: stderrCh})
36	
37		stdoutErrCh := make(chan error, 1)
38		stderrErrCh := make(chan error, 1)
39	
40		// Start goroutine to read stdout.
41		go func() {
42			defer close(stdoutCh)
43	
44			// If progress handler is set, stream progress updates.
45			if s.progressHandler != nil {
46				tee := io.TeeReader(stdoutPipe, stdoutWriter)
47				stdoutErrCh <- streamTaskProgress(tee, s.progressHandler)
48				return
49			}
50			_, copyErr := io.Copy(stdoutWriter, stdoutPipe)
51			stdoutErrCh <- copyErr
52		}()
53	
54		// Start goroutine to read stderr.
55		go func() {
56			defer close(stderrCh)
57			_, copyErr := io.Copy(stderrWriter, stderrPipe)
58			stderrErrCh <- copyErr
59		}()
60	
61		// Start goroutine to wait for nmap to finish and process the result.
62		go func() {
63			defer close(resultCh)
64	
65			runErr := cmd.Wait()
66			stdoutErr := <-stdoutErrCh
67			stderrErr := <-stderrErrCh
68	
69			result, parseErr := s.processNmapResult(&stdout, &stderr)
70			if stdoutErr != nil && !errors.Is(stdoutErr, io.EOF) && result != nil {
71				result.warnings = append(result.warnings, fmt.Sprintf("stdout stream error: %s", stdoutErr))
72			}
73			if stderrErr != nil && !errors.Is(stderrErr, io.EOF) && result != nil {
74				result.warnings = append(result.warnings, fmt.Sprintf("stderr stream error: %s", stderrErr))
75			}
76	
77			finalResult, finalErr := finalizeRun(ctx, runErr, parseErr, result, &stdout, &stderr)
78			resultCh <- RunResult{Result: finalResult, Err: finalErr}
79		}()
80	
81		return stdoutCh, stderrCh, resultCh, nil
82	}
